static int hwlink_RunFinished_verify_table(flatcc_table_verifier_descriptor_t *td)
{
    int ret;
    if ((ret = flatcc_verify_field(td, 0, 4, 4) /* total */)) return ret;
    if ((ret = flatcc_verify_field(td, 1, 2, 2) /* pass */)) return ret;
    if ((ret = flatcc_verify_field(td, 2, 2, 2) /* fail */)) return ret;
    if ((ret = flatcc_verify_field(td, 3, 2, 2) /* skip */)) return ret;
    if ((ret = flatcc_verify_field(td, 4, 2, 2) /* na */)) return ret;
    if ((ret = flatcc_verify_field(td, 5, 1, 1) /* aborted */)) return ret;
    if ((ret = flatcc_verify_field(td, 6, 1, 1) /* resumed */)) return ret;
    return flatcc_verify_ok;
}

